#include <memory>
#include <vector>
struct Source { virtual int read() const = 0; virtual ~Source() = default; };
class Direct : public Source { int value_; public: explicit Direct(int x) : value_(x) {} int read() const override { return value_; } };
class Doubled : public Source { int value_; public: explicit Doubled(int x) : value_(x) {} int read() const override { return value_*2; } };
int solve(int a,int b) { std::vector<std::unique_ptr<Source>> v; v.push_back(std::make_unique<Direct>(a)); v.push_back(std::make_unique<Doubled>(b)); int total=0; for(const auto& s:v) total+=s->read(); return total; }
